def kernel(x, g, b, eps):
    M, N = x.shape
    tile_rows = 128
    tile_cols = 512
    y = np.zeros_like(x, dtype=np.float32)

    for i in range(0, M, tile_rows):
        for j in range(0, N, tile_cols):
            end_i = min(i + tile_rows, M)
            end_j = min(j + tile_cols, N)
            tile_x = x[i:end_i, j:end_j]
            # Compute mean with explicit loop
            num_cols = end_j - j
            mean = np.zeros(num_cols, dtype=np.float32)
            for col in range(num_cols):
                total = 0.0
                for row in range(end_i - i):
                    total += tile_x[row, col]
                mean[col] = total / (end_i - i)
            # Compute variance with explicit loop
            var = np.zeros(num_cols, dtype=np.float32)
            for col in range(num_cols):
                total = 0.0
                for row in range(end_i - i):
                    diff = tile_x[row, col] - mean[col]
                    total += diff * diff
                var[col] = total / (end_i - i)
            std = np.sqrt(var + eps)
            tile_y = (tile_x - mean) / std
            # Tile g and b with explicit loops
            g_tile = np.zeros((end_i - i, num_cols), dtype=np.float32)
            for r in range(end_i - i):
                for c in range(num_cols):
                    g_tile[r, c] = g[j + c]
